// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import java.util.ArrayDeque;
import java.util.concurrent.Callable;
import java.util.function.Consumer;

/**
 * An {@link AdjacencyWorkerPool} whose submitted work runs inline, one task per {@link #runNext()}, so a test decides
 * exactly when a worker result reaches the applier.
 */
final class DirectWorkerPool implements AdjacencyWorkerPool {

	private final ArrayDeque<Runnable> queued = new ArrayDeque<>();
	private boolean shutdown;

	@Override
	public <T> void submit(Callable<T> work, Consumer<Outcome<T>> onDone) {
		if (shutdown) {
			throw new IllegalStateException("worker pool is shut down");
		}
		queued.addLast(() -> {
			Outcome<T> outcome;
			try {
				outcome = Outcome.success(work.call());
			} catch (Throwable failure) {
				outcome = Outcome.failure(failure);
			}
			onDone.accept(outcome);
		});
	}

	@Override
	public void shutdown() {
		shutdown = true;
	}

	boolean hasWork() {
		return !queued.isEmpty();
	}

	int pending() {
		return queued.size();
	}

	/** Runs the oldest submitted task and delivers its outcome; returns whether one existed. */
	boolean runNext() {
		Runnable next = queued.pollFirst();
		if (next == null) {
			return false;
		}
		next.run();
		return true;
	}

	void runAll() {
		while (runNext()) {
			// run every queued task, including ones submitted while running
		}
	}
}
